    AND l.owner_id IS NULL


    AND l.owner_id IS NOT NULL


    AND a.reviewed_by=#{reviewer_id}


    AND JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(a.structured_json) THEN
    a.structured_json ELSE '{}' END,'$.rule_result.grade'))=#{grade}


    AND JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(a.structured_json) THEN
    a.structured_json ELSE '{}' END,'$.slots.gender.value'))=#{gender}


    AND EXISTS(SELECT 1 FROM script_reach sr WHERE sr.tenant_id=c.tenant_id AND
    sr.call_id=c.id AND sr.kind='node' AND (sr.target_id=#{node} OR
    sr.target_label=#{node}))


    AND EXISTS(SELECT 1 FROM platform_contact_batch_member bm WHERE bm.tenant_id=c.tenant_id
    AND bm.contact_id=c.contact_id AND bm.batch_id=#{batch_id})


    AND c.last_error LIKE CONCAT('%',#{hangup_reason},'%')


    AND EXISTS(SELECT 1 FROM ops_history oh WHERE oh.tenant_id=c.tenant_id AND
    oh.contact_id=c.contact_id AND oh.detail_json LIKE CONCAT('%',#{remark},'%'))


    AND COALESCE(a.result_code='qualified_lead',FALSE)=#{successful}


    AND (c.mode='HUMAN_ONLY')=#{manual}


    AND EXISTS(SELECT 1 FROM handoffrequest hh WHERE hh.tenant_id=c.tenant_id AND
    hh.call_session_id=c.id)=#{entered}


    AND EXISTS(SELECT 1 FROM handoffrequest hh WHERE hh.tenant_id=c.tenant_id AND
    hh.call_session_id=c.id AND hh.state IN ('ACCEPTED','COMPLETED'))=#{taken}


    AND EXISTS(SELECT 1 FROM callevent le WHERE le.call_session_id=c.id AND
    le.event_type='handoff_lost')=#{lost}


    AND EXISTS(SELECT 1 FROM callusage cu WHERE cu.tenant_id=c.tenant_id AND
    cu.call_session_id=c.id AND cu.answered_at IS NOT NULL)=#{answered}

AND (#{allScope}=TRUE OR c.human_agent_id=#{userId}

    OR EXISTS (SELECT 1 FROM scenarioversion sv WHERE sv.tenant_id=c.tenant_id
    AND sv.campaign_id=c.campaign_id AND sv.published_by=#{userId})

OR l.owner_id=#{userId} OR EXISTS(SELECT
1 FROM handoffrequest own_h WHERE own_h.tenant_id=c.tenant_id AND own_h.call_session_id=c.id
AND own_h.assigned_agent_id=#{userId} AND own_h.state IN ('WAITING','ACCEPTING','ACCEPTED'))
OR EXISTS(SELECT 1 FROM ops_member m JOIN ops_member me ON me.tenant_id=m.tenant_id AND
me.team_id=m.team_id AND me.is_lead=TRUE JOIN ops_team t ON t.tenant_id=m.tenant_id AND
t.id=m.team_id AND t.enabled=TRUE WHERE m.tenant_id=c.tenant_id AND me.user_id=#{userId} AND
m.user_id IN (l.owner_id,c.human_agent_id)))

    AND c.id=#{id}


    AND c.phone LIKE CONCAT('%',#{phone},'%')


    AND COALESCE(dim.actor_id,g.created_by,0)=#{actor_id}


    AND COALESCE(dim.team_id,0)=#{stat_team_id}


    AND COALESCE(NULLIF(dim.city,''),'未采集')=#{city}


    AND COALESCE(NULLIF(dim.line_group,''),'未分组')=#{line_group}


    AND g.script_template_id=#{script_id}


    AND g.status=#{task_status}


    AND COALESCE(c.script_flow_version_id,0)=#{flow_version_id}


    AND c.campaign_id=#{campaign_id}


    AND c.status=#{status}


    AND c.contact_id=#{contact_id}


    AND c.human_agent_id=#{agent_id}


    AND c.telephony_line_id=#{line_id}


    AND a.intent=#{intent}


    AND a.review_state=#{review_state}


    AND c.created_at >=#{from}


    AND c.created_at <=#{until}


    AND TIMESTAMPDIFF(SECOND,c.started_at,c.finished_at)>=#{min_seconds}


    AND TIMESTAMPDIFF(SECOND,c.started_at,c.finished_at)<=#{max_seconds}


    AND EXISTS (SELECT SUM(u.telephony_seconds) AS span FROM callusage u WHERE
    u.tenant_id=c.tenant_id AND u.call_session_id=c.id AND u.answered_at IS NOT NULL HAVING

        span BETWEEN #{r.min} AND #{r.max}

    )


    AND EXISTS (SELECT SUM(u.ai_seconds) AS span FROM callusage u WHERE
    u.tenant_id=c.tenant_id AND u.call_session_id=c.id AND u.answered_at IS NOT NULL HAVING

        span BETWEEN #{r.min} AND #{r.max}

    )


    AND EXISTS (SELECT CASE WHEN c.mode='HUMAN_ONLY' THEN
    (SELECT SUM(u.telephony_seconds) FROM callusage u WHERE u.tenant_id=c.tenant_id AND
    u.call_session_id=c.id AND u.answered_at IS NOT NULL)
    ELSE (SELECT SUM(TIMESTAMPDIFF(MICROSECOND,h.responded_at,h.completed_at))/1000000 FROM
    handoffrequest h WHERE h.tenant_id=c.tenant_id AND h.call_session_id=c.id AND
    h.state='COMPLETED' AND h.completed_at >= h.responded_at) END AS span HAVING

        span BETWEEN #{r.min} AND #{r.max}

    )


    AND (c.handoff_reason IS NOT NULL AND c.handoff_reason<>'')=#{handoff}


    AND l.owner_id=#{owner_id}


    AND l.stage=#{stage}


    AND (JSON_CONTAINS(l.tags_json,JSON_QUOTE(#{tag})) OR EXISTS(SELECT 1 FROM ops_tag_link
    ot WHERE ot.tenant_id=c.tenant_id AND ot.tag=#{tag} AND ((ot.target_kind='call' AND
    ot.object_id=c.id) OR (ot.target_kind='campaign' AND ot.object_id=CAST(c.campaign_id AS
    CHAR)) OR (ot.target_kind='script' AND ot.object_id=CAST(g.script_template_id AS
    CHAR)))))


    AND EXISTS(SELECT 1 FROM ops_member tm WHERE tm.tenant_id=c.tenant_id AND
    tm.team_id=#{team_id} AND tm.user_id=COALESCE(l.owner_id,c.human_agent_id))

mapper.select:
SELECT c.*,a.intent,a.qa_score,a.review_state,a.reviewed_by,a.result_code, JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(a.structured_json) THEN a.structured_json ELSE '{}' END,'$.rule_result.grade')) AS grade, JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(a.structured_json) THEN a.structured_json ELSE '{}' END,'$.slots.gender.value')) AS gender, g.name AS campaign_name,l.owner_id,l.stage,l.updated_at AS follow_at, (SELECT MAX(oh.created_at) FROM ops_history oh WHERE oh.tenant_id=c.tenant_id AND oh.contact_id=c.contact_id AND oh.action='assign') AS assigned_at, (SELECT oh.detail_json FROM ops_history oh WHERE oh.tenant_id=c.tenant_id AND oh.contact_id=c.contact_id ORDER BY oh.id DESC LIMIT 1) AS remark, (SELECT SUM(-ve.signed_amount) FROM voice_statement_entry ve WHERE ve.tenant_id=c.tenant_id AND ve.call_id=c.id AND ve.kind='charge') AS call_cost, TIMESTAMPDIFF(SECOND,c.started_at,c.finished_at) AS duration_seconds
WHERE c.tenant_id=#{tenantId}
ORDER BY c.created_at DESC,c.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)

WHERE c.tenant_id=#{tenantId} AND c.id IN

    #{callId}

SELECT DATE_FORMAT(TIMESTAMPADD(HOUR,8,c.created_at),'%Y-%m-%d') AS day_key, COALESCE(NULLIF(a.intent,''),'unclassified') AS intent_key, COUNT(*) AS sessions, SUM(c.attempts) AS attempts, SUM(usage_data.answers) AS answers, SUM(usage_data.answers > 0) AS answered_sessions, SUM(COALESCE(usage_data.seconds,0)) AS seconds
JOIN LATERAL (SELECT COUNT(u.answered_at) AS answers,SUM(u.telephony_seconds) AS seconds FROM callusage u WHERE u.tenant_id=c.tenant_id AND u.call_session_id=c.id) usage_data ON TRUE WHERE c.tenant_id=#{tenantId}
GROUP BY day_key,intent_key ORDER BY day_key,intent_key

SELECT stats.*, ROUND(100*answered_attempts/NULLIF(attempts,0),2) AS answer_rate, ROUND(100*handoff_requests/NULLIF(reached_sessions,0),2) AS entry_rate, ROUND(100*handoff_received/NULLIF(handoff_requests,0),2) AS takeover_rate, ROUND(100*successful_calls/NULLIF(reached_sessions,0),2) AS success_per_answer, ROUND(100*successful_takeovers/NULLIF(handoff_received,0),2) AS success_per_takeover, ROUND(100*interested_sessions/NULLIF(reached_sessions,0),2) AS intent_rate FROM (SELECT CASE #{dimension} WHEN 'all' THEN 0 WHEN 'account' THEN COALESCE(dim.actor_id,g.created_by,0) WHEN 'group' THEN COALESCE(dim.team_id,0) WHEN 'city' THEN COALESCE(NULLIF(dim.city,''),'未采集') WHEN 'line_group' THEN COALESCE(NULLIF(dim.line_group,''),'未分组') WHEN 'script' THEN COALESCE(g.script_template_id,0) WHEN 'flow_version' THEN COALESCE(c.script_flow_version_id,0) WHEN 'agent' THEN COALESCE(c.human_agent_id,0) WHEN 'line' THEN COALESCE(c.telephony_line_id,0) WHEN 'owner' THEN COALESCE(l.owner_id,0) ELSE COALESCE(c.campaign_id,0) END AS dimension_key, CASE #{granularity} WHEN 'month' THEN DATE_FORMAT(TIMESTAMPADD(HOUR,8,c.created_at),'%Y-%m') WHEN 'minute' THEN DATE_FORMAT(TIMESTAMPADD(HOUR,8,c.created_at),'%Y-%m-%d %H:%i') WHEN 'hour' THEN DATE_FORMAT(TIMESTAMPADD(HOUR,8,c.created_at),'%Y-%m-%d %H:00') WHEN 'day' THEN DATE_FORMAT(TIMESTAMPADD(HOUR,8,c.created_at),'%Y-%m-%d') ELSE '全部' END AS bucket, SUM(usage_totals.first_answers) AS first_answered_attempts, SUM(usage_totals.repeat_answers) AS repeat_answered_attempts, SUM(usage_totals.first_answers + usage_totals.repeat_answers) AS answered_attempts, SUM(usage_totals.telephony_seconds) AS telephony_seconds, SUM(usage_totals.ai_seconds) AS ai_seconds, SUM(settled.amount) AS statement_cost,SUM(settled.seconds) AS bill_seconds, SUM(settled.covered) AS settled_attempts, MAX(g.name) AS campaign_name,MAX(g.status) AS campaign_status, SUM(EXISTS(SELECT 1 FROM callevent ev WHERE ev.call_session_id=c.id AND ev.event_type='agent_screen_shown')) AS screen_count, SUM(EXISTS(SELECT 1 FROM callevent ev WHERE ev.call_session_id=c.id AND ev.event_type='handoff_lost')) AS loss_count, SUM(usage_totals.short_answers) AS short_answers,SUM(usage_totals.measured) AS measured_answers, SUM(hf.short_taken) AS short_taken,SUM(hf.measured_taken) AS measured_taken, SUM(hf.wait_total) AS wait_total,SUM(hf.wait_samples) AS wait_samples, SUM(hf.human_seconds) AS human_seconds, SUM(l.stage IN ('in_progress','completed','invalid')) AS followed, COUNT(DISTINCT c.human_agent_id) AS active_agents, SUM(hf.recent_total) AS recent_wait_total,SUM(hf.recent_samples) AS recent_wait_samples, COUNT(*) AS sessions,COALESCE(SUM(c.attempts),0) AS attempts,COUNT(DISTINCT c.phone) AS phones, CASE WHEN SUM(JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(a.structured_json) THEN a.structured_json ELSE '{}' END,'$.slots.gender.value')) IN ('male','female','男','女'))>0 THEN CONCAT(SUM(JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(a.structured_json) THEN a.structured_json ELSE '{}' END,'$.slots.gender.value')) IN ('male','男')),':',SUM(JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(a.structured_json) THEN a.structured_json ELSE '{}' END,'$.slots.gender.value')) IN ('female','女'))) END AS gender_ratio, SUM(c.status IN ('ANSWERED','IN_AI','WAITING_HUMAN','HANDOFF_TRANSFERRING','IN_HUMAN','COMPLETED')) AS reached_sessions, COUNT(DISTINCT CASE WHEN c.status IN ('ANSWERED','IN_AI','WAITING_HUMAN','HANDOFF_TRANSFERRING','IN_HUMAN','COMPLETED') THEN c.phone END) AS reached_phones, SUM(CASE WHEN LEFT(UPPER(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(a.structured_json) THEN a.structured_json ELSE '{}' END,'$.rule_result.grade')),'')),1) IN ('A','B') AND usage_totals.first_answers+usage_totals.repeat_answers>0 THEN 1 ELSE 0 END) AS ab_intents, SUM(hf.entered) AS handoff_requests,SUM(hf.taken) AS handoff_received, SUM(hf.entered AND NOT hf.taken AND c.finished_at IS NOT NULL) AS not_taken, SUM(a.result_code <=> 'qualified_lead') AS successful_calls, SUM(hf.taken AND (a.result_code <=> 'qualified_lead')) AS successful_takeovers, SUM(COALESCE(a.result_code IN ('interested','qualified_lead','callback_confirmed'),0) AND usage_totals.first_answers+usage_totals.repeat_answers>0) AS interested_sessions, COUNT(DISTINCT CASE WHEN a.result_code='qualified_lead' THEN c.phone END) AS qualified_phones, SUM(c.status IN ('FAILED','NO_ANSWER','BUSY','VOICEMAIL')) AS failed_sessions
JOIN LATERAL (SELECT SUM(-v.signed_amount) AS amount,SUM(v.bill_seconds) AS seconds,COUNT(DISTINCT v.attempt) AS covered FROM voice_statement_entry v WHERE v.tenant_id=c.tenant_id AND v.call_id=c.id AND v.kind='charge' AND v.source_mode=#{statement_mode}) settled ON TRUE JOIN LATERAL (SELECT COUNT(*)>0 AS entered, COALESCE(MAX(h.state IN ('ACCEPTED','COMPLETED')),0) AS taken, COUNT(CASE WHEN h.state='COMPLETED' AND TIMESTAMPDIFF(MICROSECOND,h.responded_at,h.completed_at) BETWEEN 0 AND 5000000 THEN 1 END) AS short_taken, COUNT(CASE WHEN h.state='COMPLETED' AND h.completed_at >= h.responded_at THEN 1 END) AS measured_taken, SUM(CASE WHEN h.state='COMPLETED' AND h.completed_at>=h.responded_at THEN TIMESTAMPDIFF(MICROSECOND,h.responded_at,h.completed_at)/1000000 END) AS human_seconds, COALESCE(SUM(CASE WHEN h.responded_at>=h.requested_at AND h.state IN ('ACCEPTED','COMPLETED') THEN TIMESTAMPDIFF(MICROSECOND,h.requested_at,h.responded_at)/1000000 END),0) AS wait_total, COUNT(CASE WHEN h.responded_at>=h.requested_at AND h.state IN ('ACCEPTED','COMPLETED') THEN 1 END) AS wait_samples, COALESCE(SUM(CASE WHEN h.responded_at>=h.requested_at AND h.responded_at>=UTC_TIMESTAMP(3)-INTERVAL 5 MINUTE AND h.state IN ('ACCEPTED','COMPLETED') THEN TIMESTAMPDIFF(MICROSECOND,h.requested_at,h.responded_at)/1000000 END),0) AS recent_total, COUNT(CASE WHEN h.responded_at>=h.requested_at AND h.responded_at>=UTC_TIMESTAMP(3)-INTERVAL 5 MINUTE AND h.state IN ('ACCEPTED','COMPLETED') THEN 1 END) AS recent_samples FROM handoffrequest h WHERE h.tenant_id=c.tenant_id AND h.call_session_id=c.id) hf ON TRUE JOIN LATERAL ( SELECT COUNT(CASE WHEN u.answered_at IS NOT NULL AND u.attempt=1 THEN 1 END) AS first_answers, COUNT(CASE WHEN u.answered_at IS NOT NULL AND u.attempt>1 THEN 1 END) AS repeat_answers, COUNT(CASE WHEN u.answered_at IS NOT NULL AND u.telephony_seconds BETWEEN 0 AND 15 THEN 1 END) AS short_answers, COUNT(CASE WHEN u.answered_at IS NOT NULL AND u.telephony_seconds >= 0 THEN 1 END) AS measured, SUM(u.telephony_seconds) AS telephony_seconds, SUM(u.ai_seconds) AS ai_seconds FROM callusage u WHERE u.tenant_id=c.tenant_id AND u.call_session_id=c.id ) usage_totals ON TRUE WHERE c.tenant_id=#{tenantId}
GROUP BY dimension_key,bucket) stats WHERE 1=1
AND 100*interested_sessions/NULLIF(reached_sessions,0) >= #{min_intent_rate}
AND 100*interested_sessions/NULLIF(reached_sessions,0) <= #{max_intent_rate}
ORDER BY bucket DESC,dimension_key

SELECT grouped.*,ROUND(100*total/NULLIF(SUM(total) OVER(PARTITION BY dimension_key),0),2) AS rate FROM ( SELECT CASE #{dimension} WHEN 'campaign' THEN c.campaign_id ELSE c.human_agent_id END AS dimension_key, MAX(CASE #{dimension} WHEN 'campaign' THEN g.name ELSE (SELECT u.full_name FROM sys_user u WHERE u.tenant_id=c.tenant_id AND u.id=c.human_agent_id) END) AS dimension_name, COALESCE(a.intent,'未分类') AS intent,JSON_UNQUOTE(JSON_EXTRACT(CASE WHEN JSON_VALID(a.structured_json) THEN a.structured_json ELSE '{}' END,'$.rule_result.grade')) AS grade,COUNT(*) AS total
WHERE c.tenant_id=#{tenantId}
GROUP BY dimension_key,intent,grade) grouped ORDER BY dimension_key,intent,grade

SELECT CASE WHEN seconds IS NULL OR seconds <= 0 THEN 'unknown' WHEN seconds <= 10 THEN 'short' WHEN seconds <= 30 THEN 'medium' WHEN seconds <= 60 THEN 'long' ELSE 'extended' END AS duration_bucket, COUNT(*) AS calls FROM ( SELECT CASE #{durationKind} WHEN 'total' THEN usage_data.total_seconds WHEN 'ai' THEN usage_data.ai_seconds WHEN 'human' THEN CASE WHEN c.mode='HUMAN_ONLY' THEN usage_data.total_seconds ELSE (SELECT SUM(TIMESTAMPDIFF(MICROSECOND,h.responded_at,h.completed_at))/1000000 FROM handoffrequest h WHERE h.tenant_id=c.tenant_id AND h.call_session_id=c.id AND h.state='COMPLETED' AND h.completed_at >= h.responded_at) END END AS seconds
JOIN LATERAL (SELECT SUM(u.telephony_seconds) AS total_seconds, SUM(u.ai_seconds) AS ai_seconds,COUNT(*) AS answered FROM callusage u WHERE u.tenant_id=c.tenant_id AND u.call_session_id=c.id AND u.answered_at IS NOT NULL) usage_data ON usage_data.answered > 0 WHERE c.tenant_id=#{tenantId}
) measured GROUP BY duration_bucket

mapper.update:
UPDATE ops_team SET
name=#{name},enabled=#{enabled},settings_json=#{settings_json},revision=revision+1 WHERE
tenant_id=#{tenantId} AND id=#{team_id} AND revision=#{revision}

mapper.select:
SELECT DISTINCT c.campaign_id,g.name AS campaign_name,c.telephony_line_id,tl.name AS line_name
LEFT JOIN telephonyline tl ON tl.tenant_id=c.tenant_id AND tl.id=c.telephony_line_id WHERE c.tenant_id=#{tenantId}
LIMIT 2000

mapper.sql:
AND (#{allScope}=TRUE OR l.owner_id=#{userId} OR (#{pool}=TRUE AND l.owner_id IS NULL) OR
EXISTS(SELECT 1 FROM ops_member m JOIN ops_member me ON me.tenant_id=m.tenant_id AND
me.team_id=m.team_id AND me.is_lead=TRUE JOIN ops_team t ON t.tenant_id=m.tenant_id AND
t.id=m.team_id AND t.enabled=TRUE WHERE m.tenant_id=c.tenant_id AND me.user_id=#{userId} AND
m.user_id=l.owner_id))

    AND c.id=#{contact_id}


    AND (c.phone LIKE CONCAT('%',#{keyword},'%') OR c.name LIKE CONCAT('%',#{keyword},'%'))


    AND l.owner_id IS NULL


    AND l.owner_id=#{userId}


    AND l.owner_id=#{owner_id}


    AND COALESCE(l.stage,'open')=#{stage}


    AND l.next_at < CURRENT_TIMESTAMP(3) AND l.stage NOT IN ('completed','invalid')


    AND JSON_CONTAINS(l.tags_json,JSON_QUOTE(#{tag}))

mapper.select:
SELECT c.id AS contact_id,c.phone,c.name,c.dnc,c.consent_state,COALESCE(l.revision,0) AS revision,COALESCE((SELECT JSON_UNQUOTE(JSON_EXTRACT(wh.detail_json,'$.wecom_status')) FROM ops_history wh WHERE wh.tenant_id=c.tenant_id AND wh.contact_id=c.id AND wh.action='wecom' ORDER BY wh.id DESC LIMIT 1),'pending') AS wecom_status, COALESCE(l.stage,'open') AS stage,l.owner_id,u.full_name AS owner_name,l.next_at,l.fields_json,l.tags_json,l.form_id,l.form_revision
WHERE c.tenant_id=#{tenantId}
ORDER BY l.next_at IS NULL,l.next_at,c.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT u.* FROM sys_user u WHERE u.tenant_id=#{tenantId} AND u.role='agent' AND
u.enabled=TRUE AND u.agent_status IN ('ready','busy') AND u.last_seen_at>=#{since}

    AND u.id IN

        #{id}



    AND EXISTS(SELECT 1 FROM ops_member m JOIN ops_team t ON t.tenant_id=m.tenant_id AND
    t.id=m.team_id AND t.enabled=TRUE WHERE m.tenant_id=u.tenant_id AND m.user_id=u.id

        AND t.id IN

            #{id}



        AND
        JSON_CONTAINS(COALESCE(JSON_EXTRACT(t.settings_json,'$.routing_skills'),JSON_ARRAY()),CAST(#{skillsJson} AS JSON))

    )

ORDER BY u.last_seen_at,u.id FOR UPDATE

SELECT COUNT(*) FROM callsession WHERE tenant_id=#{tenantId} AND human_agent_id=#{agentId}
AND status IN
('DIALING','ANSWERED','IN_AI','WAITING_HUMAN','HANDOFF_TRANSFERRING','IN_HUMAN')

    AND id<>#{exclude}

SELECT u.id FROM sys_user u LEFT JOIN ops_lead l ON l.tenant_id=u.tenant_id AND l.contact_id=#{contactId} WHERE u.tenant_id=#{tenantId} AND u.role='agent' AND u.enabled=TRUE
AND u.id IN
#{id}
AND EXISTS(SELECT 1 FROM ops_member m JOIN ops_team t ON t.tenant_id=m.tenant_id AND t.id=m.team_id AND t.enabled=TRUE WHERE m.tenant_id=u.tenant_id AND m.user_id=u.id
AND t.id IN
#{id}
AND JSON_CONTAINS(COALESCE(JSON_EXTRACT(t.settings_json,'$.routing_skills'),JSON_ARRAY()),CAST(#{skillsJson} AS JSON))
)
ORDER BY (u.id=#{preferred}) DESC,(u.id=l.owner_id) DESC,u.id LIMIT 1

mapper.insert:
INSERT INTO ops_line_group_assignment(tenant_id,line_id,group_name)
VALUES(#{tenantId},#{line},#{group})
ON DUPLICATE KEY UPDATE group_name=#{group}

mapper.select:
SELECT category,label,COUNT(*) AS amount FROM (
SELECT '拦截统计' AS category,SUBSTRING(last_error,18) AS label FROM callsession WHERE
tenant_id=#{tenantId} AND last_error LIKE 'precheck failed: %' AND updated_at BETWEEN
#{from} AND #{until}
UNION ALL SELECT '跟进统计',action FROM ops_history WHERE tenant_id=#{tenantId} AND created_at
BETWEEN #{from} AND #{until}
UNION ALL SELECT '短信统计',state FROM msg_message WHERE tenant_id=#{tenantId} AND created_at
BETWEEN #{from} AND #{until}
) facts GROUP BY category,label ORDER BY category,amount DESC,label
